[14909] = { "Обпалююче світло", "Збільшує завдану вами шкоду святістю на {1}%. Окрім того, з ймовірністю {2}% коли ваше закляття \"Священний вогонь\" завдає періодичної шкоди, ваш наступний \"Священний спалах\" не витрачатиме мани.#by {1}%#a {2}% chance", en="Searing Light" },
