[15487] = { "Знемовлення", "Знемовлює ціль, унеможливлюючи вимову заклять протягом {1} с, а також перериває вимову заклять на {2} с.#spells for {1} sec#casts for {2} sec", "Знемовлено.", en="Silence" },
