[14523] = { "Мовчазна рішучість", "Зменшує рівень загрози від ваших заклять на {1}% та скорочує тривалість ефектів приголомшення, страху та знемовлення, що діють на вас, на {2}%.#by {1}% and#you by {2}%", en="Silent Resolve" },
